"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[66190],{3331:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>s});var r=i(36672);const t={},a=r.createContext(t);function o(e){const n=r.useContext(a);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),r.createElement(a.Provider,{value:n},e.children)}},24106:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>v,frontMatter:()=>o,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semafoor: Een volledig toetsenbord","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/nl/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13 april 2023","top_news":"Semafoor: Een volledig toetsenbord"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/nl/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/nl/2023/04/12"}}');var t=i(23420),a=i(3331);const o={localized_date:"13 april 2023",top_news:"Semafoor: Een volledig toetsenbord"},s="2023-04-13",d={},l=[{value:"Semafoor: Een volledig toetsenbord",id:"semafoor-een-volledig-toetsenbord",level:2},{value:"Toon GPT-4-aangedreven webzoekopdrachten voor ontwikkelaars",id:"toon-gpt-4-aangedreven-webzoekopdrachten-voor-ontwikkelaars",level:2},{value:"Mijn beste vrienden vervangen door een LLM getraind op 500k groeps-chatberichten",id:"mijn-beste-vrienden-vervangen-door-een-llm-getraind-op-500k-groeps-chatberichten",level:2},{value:"NPR stapt uit Twitter na te zijn bestempeld als &#39;aan de staat gelieerde media&#39;.",id:"npr-stapt-uit-twitter-na-te-zijn-bestempeld-als-aan-de-staat-gelieerde-media",level:2},{value:"Massaontslagen en afwezige bazen zorgen voor een morele crisis bij Meta",id:"massaontslagen-en-afwezige-bazen-zorgen-voor-een-morele-crisis-bij-meta",level:2},{value:"Hetzner introduceert ARM64 Cloud Servers",id:"hetzner-introduceert-arm64-cloud-servers",level:2},{value:"Nieuwe NASA-directeur zweert eed op Carl Sagan&#39;s &#39;Pale Blue Dot&#39; in plaats van Bijbel",id:"nieuwe-nasa-directeur-zweert-eed-op-carl-sagans-pale-blue-dot-in-plaats-van-bijbel",level:2},{value:"Intel Foundry Services en Arm kondigen samenwerking aan op het gebied van SoC-ontwerp",id:"intel-foundry-services-en-arm-kondigen-samenwerking-aan-op-het-gebied-van-soc-ontwerp",level:2},{value:"EVE Online-speler gebruikt obscure regel om grootste overval in de geschiedenis van het spel te plegen",id:"eve-online-speler-gebruikt-obscure-regel-om-grootste-overval-in-de-geschiedenis-van-het-spel-te-plegen",level:2},{value:"Virtuele draden komen in JDK 21, en luiden een nieuw tijdperk van gelijktijdigheid in.",id:"virtuele-draden-komen-in-jdk-21-en-luiden-een-nieuw-tijdperk-van-gelijktijdigheid-in",level:2}];function g(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,t.jsx)(n.h2,{id:"semafoor-een-volledig-toetsenbord",children:"Semafoor: Een volledig toetsenbord"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Origineel"}),".\nSemafoor is een full-body toetsenbord dat OpenCV en MediaPipe's Pose detection gebruikt om lichaamskenmerken van video-input te detecteren, relatieve verschillen te berekenen, en deze te vertalen in toetsen en commando's die via het toetsenbord verstuurd worden. De primaire invoer bestaat uit het \"typen\" van letters, cijfers en symbolen via een vlaggenmast door beide armen in verschillende hoeken uit te strekken, met andere modificatiebewegingen voor functies als shift, backspace en pijltjestoetsen. Het draait op de nieuwste MacOS en is toegankelijk via de terminal met behulp van een aangepaste toetsenbordbibliotheek."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nEen toetsenbordsysteem genaamd Semaphore, dat gebruik maakt van fysieke gebaren, heeft positieve feedback gekregen van Discussion Service-gebruikers en heeft implicaties voor werknemers op afstand die lichaamsbeweging en programmeren willen combineren. Gebruikers bespreken het combineren van Semaphore met stenografie, muzieknoten, yoga-oefeningen en programmeren, en sommigen wijzen op het potentieel voor verhoogde effici\xebntie door de toevoeging van functies zoals een autocomplete."]}),"\n",(0,t.jsx)(n.h2,{id:"toon-gpt-4-aangedreven-webzoekopdrachten-voor-ontwikkelaars",children:"Toon GPT-4-aangedreven webzoekopdrachten voor ontwikkelaars"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.phind.com",children:"Origineel"}),".\nDe website 'phind.com' is momenteel ontoegankelijk, omdat deze een beveiligingsdienst gebruikt om zichzelf te beschermen tegen online aanvallen die kunnen zijn veroorzaakt door bepaalde acties, zoals het indienen van een bepaald woord of een bepaalde zin, een SQL-commando of misvormde gegevens. Om dit op te lossen, kunnen gebruikers de eigenaar van de site een e-mail sturen met details over wat ze deden toen de blokkade optrad en de Cloudflare Ray ID die onder aan de pagina staat."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nDe door GPT-4 aangedreven zoekmachine van Phind.com biedt nauwkeurige coderingsantwoorden en gedetailleerde uitleg via aangepaste filters, en er zijn modellen voor het delen van inkomsten onderzocht voor producenten van inhoud, hoewel er bezorgdheid bestaat over de modelleringskosten; gebruikers hebben de dienst geprezen om zijn duidelijke informatie, effici\xebntie en waardevolle aanvullende informatie, hoewel er enkele problemen met de nauwkeurigheid van de zoekopdrachten zijn opgemerkt. Sommige gebruikers hebben kritiek op het vermogen van GPT-4 om problemen op te lossen en zetten vraagtekens bij de nauwkeurigheid en relevantie, maar het Phind-team heeft hierop gereageerd door een nieuwe versie uit te brengen met een Expert-modus."]}),"\n",(0,t.jsx)(n.h2,{id:"mijn-beste-vrienden-vervangen-door-een-llm-getraind-op-500k-groeps-chatberichten",children:"Mijn beste vrienden vervangen door een LLM getraind op 500k groeps-chatberichten"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Origineel"}),".\nEen LLM werd getraind op de ongecensureerde groepschatberichten van Izzy Miller uit zijn studententijd, wat resulteerde in betere gesprekken met zijn beste vrienden. De dataset bestond uit 500k berichten, en Miller maakte er sessies van om het modelleren te vergemakkelijken. Het resulterende model genereerde volledige conversaties en legde de contextuele essentie van de groepschat vast. Het artikel legt uit hoe LLaMA-gewichten kunnen worden omgezet in een formaat dat compatibel is met de Transformers-bibliotheek met behulp van Python-codering, inclusief het belang van een goede voorziening van schijfruimte."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nSommige Discussion Service-gebruikers uiten hun bezorgdheid over de ethische implicaties van het maken van digitale kopie\xebn van personen met behulp van persoonlijke gegevens, terwijl anderen stellen dat bestaande wetten en morele/sociale druk nog steeds van toepassing zijn. Critici waarschuwen voor mogelijke snode toepassingen van LLM-technologie door autocratische regimes of voor winstbejag. Er is verdeeldheid ontstaan over AI-technologie, met zorgen over de ongeteste impact ervan op de privacy en hyperscepsis over de doeltreffendheid ervan. Er is controverse over het gebruik van AI-chatbots en hun potentieel om menselijke contacten te vervangen, evenals ethische bezwaren tegen tekstaanvulhulpmiddelen waarmee digitale simulaties van verloren dierbaren kunnen worden gemaakt."]}),"\n",(0,t.jsx)(n.h2,{id:"npr-stapt-uit-twitter-na-te-zijn-bestempeld-als-aan-de-staat-gelieerde-media",children:"NPR stapt uit Twitter na te zijn bestempeld als 'aan de staat gelieerde media'."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Origineel"}),'.\nNPR heeft zijn Twitter-activiteiten stopgezet nadat Twitter hen als "aan de staat gelieerde media" bestempelde, een label dat volgens NPR onjuist en misleidend is. Dit besluit beschermt de geloofwaardigheid van NPR en zorgt ervoor dat ze journalistiek kunnen produceren zonder negativiteit. Elon Musk gaf toe dat hij er misschien naast zat met het label en verandert het misschien in "publiek gefinancierd".']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nNPR kreeg te maken met kritiek en stopte uiteindelijk met Twitter nadat het als "staatsgeaffilieerde media" werd bestempeld vanwege overheidsfinanciering, wat leidde tot een debat over de criteria voor een dergelijke etikettering en of het NPR nauwkeurig karakteriseert als een nieuwsorganisatie met redactionele onafhankelijkheid. Sommige Discussion Service-gebruikers suggereren dat andere bedrijven, waaronder de bedrijven van Elon Musk, onder deze categorie vallen vanwege overheidsfinanciering. De commentaren benadrukken ook de complexe relatie tussen media, financieringsbronnen en redactionele onafhankelijkheid, waarbij sommigen NPR beschuldigen van linkse vooringenomenheid en anderen haar transparantie en onafhankelijkheid verdedigen.']}),"\n",(0,t.jsx)(n.h2,{id:"massaontslagen-en-afwezige-bazen-zorgen-voor-een-morele-crisis-bij-meta",children:"Massaontslagen en afwezige bazen zorgen voor een morele crisis bij Meta"}),"\n",(0,t.jsxs)(n.p,{children:["(",(0,t.jsx)(n.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html"}),").\nHet moreel bij het moederbedrijf van Facebook, Meta, daalt door massaontslagen en afwezige bazen, wat de werknemers zorgen baart. De leiding van het bedrijf wordt ook in twijfel getrokken door de werknemers."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nDeskundigen bespreken uiteenlopende meningen over de toekomst van geavanceerde technologie\xebn zoals generatieve AI, VR en cryptocurrency. Terwijl sommigen pleiten voor specifieke gebruikscases van generatieve AI en vooruitgang in generatieve media, worden zorgen geuit over het potentieel om banen in de middenklasse te automatiseren en de nauwkeurigheid van generatieve AI-modellen. Bedrijven kijken naar generatieve AI om de AR/VR-technologiemarkt te helpen versnellen, en het succes van de apparaten van Meta Labs wordt afgezet tegen het onzekere succes van de headset van Apple. De crypto-industrie wordt door sommigen gezien als een affiniteitszwendel, maar Bitcoin wordt door anderen nog steeds anders bekeken."]}),"\n",(0,t.jsx)(n.h2,{id:"hetzner-introduceert-arm64-cloud-servers",children:"Hetzner introduceert ARM64 Cloud Servers"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Origineel"}),".\nDe Duitse hosting- en cloudprovider Hetzner heeft vier nieuwe Hetzner Cloud-servers op basis van Arm64-technologie gelanceerd, waarmee het bedrijf de processors voor het eerst gebruikt. De servers bieden maximaal 16 vCPU's en worden gecombineerd met maximaal 32 GB ECC RAM en maximaal 320 GB NVMe SSD-gebaseerde opslag. De nieuwe reeks servers begint bij een prijs van \u20ac 3,79 ($ 4,54) per maand, en heeft factureringsopties per uur die de kosten voor klanten zullen verlagen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner heeft ARM64-cloudservers uitgebracht die minder duur zijn en beter presteren dan AWS. Over cloud-infrastructuur bestaan gemengde meningen, omdat sommigen pleiten voor betrouwbaarheid en schaalbaarheid, terwijl anderen eenvoudiger opstellingen betrouwbaarder en kosteneffectiever vinden. Het aanbod van Hetzner vult een gat voor wie Docker wil draaien zonder alle diensten te configureren, maar het is misschien niet geschikt voor beveiligingsbewuste bedrijven vanwege de zwakkere fysieke toegangscontrole. Sommigen hebben accountverboden gemeld vanwege het strenge fraudebeleid van Hetzner, en er zijn vragen over de duurzaamheid van de lage prijzen in Europa vanwege de hoge energiekosten."]}),"\n",(0,t.jsx)(n.h2,{id:"nieuwe-nasa-directeur-zweert-eed-op-carl-sagans-pale-blue-dot-in-plaats-van-bijbel",children:"Nieuwe NASA-directeur zweert eed op Carl Sagan's 'Pale Blue Dot' in plaats van Bijbel"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Origineel"}),'.\nMakenzie Lystrup, de pas benoemde directeur van NASA\'s Goddard Space Flight Center, heeft een onconventionele eed afgelegd op Carl Sagan\'s boek "Pale Blue Dot" uit 1994 in plaats van op de Bijbel. Het boek van de astronoom is ge\xefnspireerd op de beroemde Pale Blue Dot-foto van de aarde die in 1990 door de Voyager 1-ruimtesonde werd gemaakt, en Lystrup beweert dat hij "er alles aan gelegen is de volgende generatie vernieuwers te laten groeien". Het personeel van Goddard Space Flight Center bestaat uit 10.000 werknemers, zowel ambtenaren als contractanten, en het centrum is verantwoordelijk voor de uitvoering van een portefeuille van 4 miljard dollar.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nDe nieuwe NASA-directeur wordt be\xebdigd op Carl Sagan\'s "Pale Blue Dot", wat een debat op gang brengt over de doeltreffendheid van eden, de betekenis van heilige teksten, persoonlijke waarden versus religieuze teksten, en de ware betekenis van persoonlijke verantwoordelijkheid. Sommigen beweren dat het zweren op een boek dat iemands waarden vertegenwoordigt passender is, terwijl anderen het nodig vinden een afbeelding van een godheid te hebben als borg voor de eed. Het zweren heeft een rituele functie en is gebruikt om samenlevingen en de geschiedenis vorm te geven, maar uiteindelijk bevat het artikel geen nieuwe of spannende informatie voor deskundigen op dit gebied.']}),"\n",(0,t.jsx)(n.h2,{id:"intel-foundry-services-en-arm-kondigen-samenwerking-aan-op-het-gebied-van-soc-ontwerp",children:"Intel Foundry Services en Arm kondigen samenwerking aan op het gebied van SoC-ontwerp"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Origineel"}),".\nIntel Foundry Services (IFS) en Arm zijn een multigeneratiesamenwerking overeengekomen om de ontwikkeling van rekenkrachtarme systeem-op-chips (SoC's) voor mobiele apparaten en andere industrie\xebn mogelijk te maken. Door de samenwerking zullen de veilige en energiezuinige processoren van Arm worden gecombineerd met de productiecapaciteit van IFS, die zowel in de VS als in de EU is gevestigd, en zullen nieuwe, baanbrekende transistortechnologie\xebn voor een beter vermogen en betere prestaties worden geleverd op het Intel 18A-proces. Deze samenwerking maakt een meer gebalanceerde wereldwijde toeleveringsketen mogelijk voor klanten van gieterijen die werken aan mobiel SoC-ontwerp op Arm-gebaseerde CPU-kernen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services werkt samen met Arm om SoC's te ontwerpen en ondervindt daarbij concurrentie van TSMC, dat al langer samenwerkt met Arm. Discussion Service-gebruikers bespreken de voor- en nadelen van de Mac Studio en vergelijken deze met andere PC-opties, met kritiek op de beperkingen van de Mac voor gaming en CAD-software. Het artikel en de commentaren gaan over alternatieven voor IOT-apparaten en productie, Intels 2 nm-productie en speculaties over Intels vermogen om hun beloften waar te maken, terwijl ook het belang van stroomverbruik, prijs en draadloze mogelijkheden bij de ontwikkeling van IOT-apparaten wordt erkend."]}),"\n",(0,t.jsx)(n.h2,{id:"eve-online-speler-gebruikt-obscure-regel-om-grootste-overval-in-de-geschiedenis-van-het-spel-te-plegen",children:"EVE Online-speler gebruikt obscure regel om grootste overval in de geschiedenis van het spel te plegen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Origineel"}),'.\nEen EVE Online-speler heeft de grootste overval in de geschiedenis van het spel gepleegd door gebruik te maken van het "aandelenmechanisme", wat resulteerde in een buit van meer dan $22.300 aan echt geld. Het ging erom de controle over Event Horizon Expeditionaries over te nemen via een schone account, aandelen over te dragen en de bedrijfsportemonnee te beroven van 130 miljard ISK en meerdere schepen, waarbij de totale waarde van de buit wordt geschat op 2,23 biljoen ISK. Het aandelensysteem is potentieel te gemakkelijk uit te buiten, volgens een Reddit thread uit 2014, en deze strategie is al eerder getest.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nEen speler heeft een succesvolle overval georkestreerd in EVE Online, waardoor vragen zijn gerezen over de bedrijfsmechanismen en de exploitatierisico's van het spel. De overval werd gezien als cool en een hoogtepunt van het spel, maar sommigen bekritiseren de financi\xeble focus en mechanismen van het spel, waaronder de waarde van de in-game valuta en het stemsysteem voor bedrijven."]}),"\n",(0,t.jsx)(n.h2,{id:"virtuele-draden-komen-in-jdk-21-en-luiden-een-nieuw-tijdperk-van-gelijktijdigheid-in",children:"Virtuele draden komen in JDK 21, en luiden een nieuw tijdperk van gelijktijdigheid in."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Origineel"}),".\nN/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nDe virtuele threads van JDK 21 verminderen de fysieke threads voor concurrency en vereenvoudiging van io-intensieve toepassingen, maar er ontstaan discussies over geheugenbeheer. Java wordt vergeleken met Go, en frameworks als Spring, Spring Boot en Quarkus bieden alternatieven voor Ruby on Rails, terwijl het debat over Java versus Go gaat over prestaties, observeerbaarheid, degelijkheid van typesystemen en interop. Het artikel staat stil bij de niche van JVM en hoe verschillende implementaties de gebruikerservaring kunnen be\xefnvloeden, waarbij vergelijkingen met C# en JetBrains Rider worden genoemd."]})]})}function v(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);